590	        assert!(
591	            body["keys"].is_null(),
592	            "no key array should be returned: {body}"
593	        );
594	    }
595	
596	    /// An app that fetches the set before the instance has ever sent anything must still get
597	    /// a key to pin — otherwise it cannot verify the very first notification it receives.
598	    #[tokio::test]
599	    async fn the_first_fetch_mints_the_instances_first_sender_key() {
600	        let state = state_with_notifications().await;
601	        seed_account(&state, "did:plc:notifroutes").await;
602	
603	        let auth = format!("Bearer {}", token(&state, "did:plc:notifroutes"));
604	        let (status, body) = call(
605	            state.clone(),
606	            Request::get("/v1/notifications/sender-keys")
607	                .header("authorization", auth)
608	                .body(Body::empty())
609	                .unwrap(),
610	        )
611	        .await;
612	        assert_eq!(status, StatusCode::OK);
613	        assert_eq!(body["keys"].as_array().unwrap().len(), 1);
614	    }
615	}
