3	//! The sending side of the notification relay: `notify_device(state, did, payload)` and
4	//! `notify_admin_devices` turn a notification into one HPKE-sealed, length-quantized payload
5	//! *per registered device* and hand each to the relay worker. Inert when
6	//! `[notifications] relay` is unset (`AppState.notify_sender` is `None`), down to never
7	//! minting key material.
8	//!
9	//! Three properties this module is responsible for, in the order they matter:
10	//!
11	//! 1. **Confidentiality.** The relay and Apple both handle the payload, and neither may read
12	//!    it. Every send is sealed to one specific device's notification public key.
13	//! 2. **Authenticity.** HPKE `mode_auth` proves the payload came from this instance's sender
14	//!    key. A malicious relay can drop or duplicate a push; it cannot author one that renders
15	//!    as genuine. Sender keys are minted lazily, on first send or first `sender-keys` fetch
16	//!    (`active_sender_key`, `published_sender_keys`).
17	//! 3. **Metadata minimization.** Ciphertext length is visible to everyone on the path, and
18	//!    notification *length* betrays notification *kind*. Every payload is padded up to a
19	//!    bucket before sealing, computed against the serialized APNs body via the shared
20	//!    `notify_relay::protocol::apns_envelope` (see `pad_len_for`); a payload too large for
21	//!    the top bucket is dropped, never sent unpadded or truncated (see `seal_for`).
22	//!
23	//! Fan-out is one seal per registration, never one seal reused: HPKE seals to a single
24	//! recipient key, and reusing an encapsulated key across devices would be a different (and
25	//! weaker) protocol. The sealing key is loaded once per fan-out.
26	//!
27	//! Nothing here is fallible from a caller's perspective. Every path ends in an enqueue or a
28	//! log line, because a notification is a courtesy: a missed banner is recovered the next time
29	//! the app talks to Custos, whereas a trigger that fails because a push relay is unwell has
30	//! turned a courtesy into an outage.
31	
32	use serde::Serialize;
33	use zeroize::Zeroizing;
34	
35	use crate::app::AppState;
36	use crate::db::notifications as store;
37	use crate::notify_relay_client::{NotifyJob, RegistrationOwner};
38	
39	/// The plaintext a device's Notification Service Extension decrypts and renders.
40	///
41	/// Serialized camelCase, matching the wallet's decoder. `pad` is the length-quantizing
42	/// filler; it is meaningless to the reader and is the last field so the arithmetic below can
43	/// reason about it as a suffix.
44	#[derive(Debug, Clone, Serialize)]
45	#[serde(rename_all = "camelCase")]
46	pub struct NotificationPayload {
47	    /// Machine-readable kind, e.g. `agent_claim_pending`. The app routes on this.
48	    #[serde(rename = "type")]
49	    pub kind: &'static str,
50	    pub title: String,
51	    pub body: String,
52	    #[serde(skip_serializing_if = "Option::is_none")]
53	    pub data: Option<serde_json::Value>,
54	    /// Spaces, sized so the serialized APNs body lands on a padding bucket.
55	    pub pad: String,
56	}
57	
58	impl NotificationPayload {
59	    /// A payload with no padding yet — [`seal_for`] computes and applies it.
60	    pub fn new(kind: &'static str, title: impl Into<String>, body: impl Into<String>) -> Self {
61	        Self {
62	            kind,
63	            title: title.into(),
64	            body: body.into(),
65	            data: None,
66	            pad: String::new(),
67	        }
68	    }
69	
70	    /// Attach structured routing data (a claim attempt id, a subject DID, …).
71	    pub fn with_data(mut self, data: serde_json::Value) -> Self {
72	        self.data = Some(data);
73	        self
74	    }
75	}
76	
77	/// Notify every device registered to `did`.
78	///
79	/// Silent and harmless when notifications are unconfigured, when the account has no
80	/// registered devices, or when the relay is unreachable. Returns how many sealed payloads
81	/// were enqueued toward the relay — delivery stays fire-and-forget beyond that, but "zero
82	/// devices could even be attempted" is a fact some triggers branch on (the consent push
83	/// makes number matching mandatory only when a push actually went out).
84	pub async fn notify_device(state: &AppState, did: &str, payload: NotificationPayload) -> usize {
85	    let Some(sender) = state.notify_sender.as_ref() else {
86	        return 0;
87	    };
88	    let registrations = match store::list_registrations(&state.db, did).await {
89	        Ok(rows) => rows,
90	        Err(e) => {
91	            tracing::warn!(error = %e, "failed to load notification registrations");
92	            return 0;
93	        }
94	    };
95	    fan_out(state, sender, registrations, payload, |device_id| {
96	        RegistrationOwner::Account {
97	            did: did.to_string(),
98	            device_uuid: device_id,
99	        }
100	    })
101	    .await
102	}
103	
104	/// Notify every *active* admin-companion device — the operator alert channel.
105	///
106	/// The registration and key-pinning halves ship here; the operator *triggers* that call this
107	/// (labeler flags, health alerts) land with admin-companion adoption, so nothing in-tree
108	/// invokes it yet. Kept rather than deferred because the admin registration route it serves
109	/// is already live — a stored registration nothing can ever send to would be the odder state.
110	#[allow(dead_code)]
111	pub async fn notify_admin_devices(state: &AppState, payload: NotificationPayload) {
112	    let Some(sender) = state.notify_sender.as_ref() else {
113	        return;
114	    };
115	    let registrations = match store::list_active_admin_registrations(&state.db).await {
116	        Ok(rows) => rows,
117	        Err(e) => {
118	            tracing::warn!(error = %e, "failed to load admin notification registrations");
119	            return;
120	        }
121	    };
122	    fan_out(state, sender, registrations, payload, |device_id| {
123	        RegistrationOwner::AdminDevice {
124	            admin_device_id: device_id,
125	        }
126	    })
127	    .await;
128	}
129	
130	/// Seal-and-enqueue one payload per registration, returning how many jobs were enqueued.
131	async fn fan_out(
132	    state: &AppState,
133	    sender: &crate::notify_relay_client::NotifySender,
134	    registrations: Vec<store::RegistrationRow>,
135	    payload: NotificationPayload,
136	    owner_of: impl Fn(String) -> RegistrationOwner,
137	) -> usize {
138	    if registrations.is_empty() {
139	        return 0;
140	    }
141	
142	    // Load the sealing key once for the whole fan-out. Doing it per device would mean a
143	    // rotation landing mid-fan-out seals some devices under the old key and some under the
144	    // new — both valid, but needlessly hard to reason about when debugging a delivery.
145	    let Some((kid, secret)) = active_sender_key(state).await else {
146	        return 0;
147	    };
148	
149	    let mut enqueued = 0;
150	    for registration in registrations {
151	        // A registration with no handle has not completed its relay round trip yet (the
152	        // relay was down at registration time, or the job is still queued). There is nothing
153	        // to push to; the next registration attempt mints one.
154	        let Some(handle) = registration.push_handle.clone() else {
155	            continue;
156	        };
157	
158	        let recipient =
159	            match crypto::p256_public_key_from_did_key(&registration.notification_public_key) {
160	                Ok(key) => key,
161	                Err(e) => {
162	                    // Registration validated this key, so reaching here means the stored row is
163	                    // corrupt — worth an error, not a silent skip.
164	                    tracing::error!(error = %e, "stored notification public key is unusable");
165	                    continue;
166	                }
167	            };
168	
169	        let Some(sealed) = seal_for(kid, &secret, &recipient, &payload) else {
170	            continue;
171	        };
172	
173	        // `send` fails only once every receiver is gone, i.e. the worker has stopped. Not
174	        // worth a per-device log line.
175	        sender.send(NotifyJob::Push {
176	            owner: owner_of(registration.device_id),
177	            handle,
178	            kid,
179	            enc: base64url(&sealed.enc),
180	            ct: base64url(&sealed.ct),
181	        });
182	        enqueued += 1;
183	    }
184	    enqueued
185	}
186	
187	/// Pad, then seal, one payload for one recipient.
188	///
189	/// Returns `None` when the payload cannot be sent — which for v1 means only one thing: it is
190	/// too large for the top padding bucket. We refuse rather than degrade. Sending it unpadded
191	/// would leak the exact length that padding exists to hide, and truncating the body would
192	/// deliver a security notice that no longer says what happened; a dropped banner is the one
193	/// failure mode with no downside beyond the missed banner itself.
194	fn seal_for(
195	    kid: i64,
196	    sender_secret: &[u8; 32],
197	    recipient_public_key: &[u8],
198	    payload: &NotificationPayload,
199	) -> Option<crypto::SealedNotification> {
200	    let pad_len = pad_len_for(kid, payload)?;
201	
202	    let mut padded = payload.clone();
203	    padded.pad = " ".repeat(pad_len);
204	    let plaintext = match serde_json::to_vec(&padded) {
205	        Ok(bytes) => bytes,
206	        Err(e) => {
207	            tracing::error!(error = %e, "failed to serialize a notification payload");
208	            return None;
209	        }
210	    };
211	
212	    match crypto::seal_notification(sender_secret, recipient_public_key, &plaintext) {
213	        Ok(sealed) => Some(sealed),
214	        Err(e) => {
215	            tracing::error!(error = %e, "failed to seal a notification");
216	            None
217	        }
218	    }
219	}
220	
221	/// How many pad bytes make this payload's APNs body land on a bucket.
222	///
223	/// The buckets are defined on the **serialized APNs request body**, because that is the only
224	/// length anyone on the path actually measures. So this models the exact body the relay will
225	/// build (via the shared [`notify_relay::protocol::apns_envelope`]) and works backwards
226	/// through base64url expansion. Sealing is deterministic in length — ciphertext is plaintext
227	/// plus a 16-byte tag, and `enc` is always a 65-byte point — so this needs no trial seal.
228	fn pad_len_for(kid: i64, payload: &NotificationPayload) -> Option<usize> {
229	    let unpadded_plaintext_len = serde_json::to_vec(payload).ok()?.len();
230	    let unpadded_ct_len = unpadded_plaintext_len + AEAD_TAG_LEN;
231	
232	    // Placeholder strings of the right *length*: only the byte count reaches the arithmetic,
233	    // and JSON escaping never touches base64url's alphabet.
234	    let envelope = notify_relay::protocol::apns_envelope(
235	        kid as u32,
236	        &"A".repeat(crypto::base64url_len(P256_POINT_LEN)),
237	        &"A".repeat(crypto::base64url_len(unpadded_ct_len)),
238	    );
239	    let unpadded_serialized_len = serde_json::to_vec(&envelope).ok()?.len();
240	
241	    let pad = crypto::plaintext_pad_len(unpadded_ct_len, unpadded_serialized_len);
242	    if pad.is_none() {
243	        tracing::error!(
244	            serialized_len = unpadded_serialized_len,
245	            "refusing to send a notification too large for any padding bucket; \
246	             sending it unpadded would leak the length padding exists to hide"
247	        );
248	    }
249	    pad
250	}
251	
252	/// AES-GCM authentication tag, appended to every ciphertext.
253	const AEAD_TAG_LEN: usize = 16;
254	
255	/// Uncompressed SEC1 P-256 point — the fixed wire length of the HPKE encapsulated key.
256	const P256_POINT_LEN: usize = 65;
257	
258	/// The sender key to seal with, generating the instance's first one on demand.
259	///
260	/// Lazy generation rather than a startup step: an instance that has notifications configured
261	/// but never sends one should not mint key material, and the first send is the earliest
262	/// moment the key is genuinely needed.
263	async fn active_sender_key(state: &AppState) -> Option<(i64, Zeroizing<[u8; 32]>)> {
264	    let master_key = master_key(state)?;
265	
266	    let existing = match store::get_active_sender_key(&state.db).await {
267	        Ok(row) => row,
268	        Err(e) => {
269	            tracing::warn!(error = %e, "failed to load the notification sender key");
270	            return None;
271	        }
272	    };
273	
274	    if let Some(row) = existing {
275	        return match crypto::decrypt_secret_bytes(&row.secret_key_encrypted, master_key) {
276	            Ok(bytes) => to_scalar(&bytes).map(|scalar| (row.kid, scalar)),
277	            Err(e) => {
278	                tracing::error!(error = %e, kid = row.kid, "failed to unwrap a sender key");
279	                None
280	            }
281	        };
282	    }
283	
284	    generate_sender_key(state, master_key).await
285	}
286	
287	/// Mint, wrap, and store a fresh sender key.
288	pub(crate) async fn generate_sender_key(
289	    state: &AppState,
290	    master_key: &[u8; 32],
291	) -> Option<(i64, Zeroizing<[u8; 32]>)> {
292	    let keypair = match crypto::generate_p256_keypair() {
293	        Ok(keypair) => keypair,
294	        Err(e) => {
295	            tracing::error!(error = %e, "failed to generate a notification sender key");
296	            return None;
297	        }
298	    };
299	    // Stays in `Zeroizing` the whole way. The crypto crate deliberately hands back a wiped-on-
300	    // drop buffer, and copying out into a bare `[u8; 32]` would silently discard that — leaving
301	    // the instance's sender scalar in freed memory on every send.
302	    let secret = keypair.private_key_bytes.clone();
303	    let wrapped = match crypto::encrypt_secret_bytes(&*secret, master_key) {
304	        Ok(wrapped) => wrapped,
305	        Err(e) => {
306	            tracing::error!(error = %e, "failed to wrap a notification sender key");
307	            return None;
308	        }
309	    };
310	    match store::insert_sender_key(&state.db, &wrapped).await {
311	        Ok(kid) => {
312	            tracing::info!(kid, "generated a new notification sender key");
313	            Some((kid, secret))
314	        }
315	        Err(e) => {
316	            tracing::error!(error = %e, "failed to store a notification sender key");
317	            None
318	        }
319	    }
320	}
321	
322	/// The published sender-key set: `(kid, did:key)` for every key a device may verify against.
323	///
324	/// This is the re-pin surface both `sender-keys` routes serve. Generating the first key here
325	/// as well as on send matters for onboarding order: an app that fetches the set before the
326	/// instance has ever sent anything would otherwise pin an empty set and be unable to verify
327	/// the first notification it receives.
328	pub async fn published_sender_keys(state: &AppState) -> Result<Vec<(i64, String)>, SenderKeyError> {
329	    // No master key means no key can be minted *or* unwrapped, so the honest answer is an
330	    // error, not an empty set. Answering `200 {"keys": []}` would let a client conclude it has
331	    // successfully pinned nothing — and then fail to verify every notification it receives,
332	    // with only a server-side warning to explain it. This is a misconfiguration; it should be
333	    // as visible as one.
334	    let master_key = master_key(state).ok_or(SenderKeyError::NoMasterKey)?;
335	
336	    let mut rows = store::list_publishable_sender_keys(&state.db).await?;
337	    if rows.is_empty() {
338	        generate_sender_key(state, master_key).await;
339	        rows = store::list_publishable_sender_keys(&state.db).await?;
340	    }
341	
342	    let keys: Vec<(i64, String)> = rows
343	        .into_iter()
344	        .filter_map(|row| {
345	            // An individual row that will not unwrap is skipped rather than fatal: it is a
346	            // key this instance can no longer use, and dropping it from the published set is
347	            // exactly right — but it must not take the still-good keys down with it.
348	            let secret = crypto::decrypt_secret_bytes(&row.secret_key_encrypted, master_key)
349	                .ok()
350	                .and_then(|bytes| to_scalar(&bytes))
351	                .or_else(|| {
352	                    tracing::error!(kid = row.kid, "a stored sender key will not unwrap");
353	                    None
354	                })?;
355	            // Re-derive the public half rather than storing it: one stored secret cannot
356	            // disagree with a separately stored public key if there is no separately stored
357	            // public key.
358	            let keypair = crypto::p256_keypair_from_secret(&secret).ok()?;
359	            Some((row.kid, keypair.key_id.0))
360	        })
361	        .collect();
362	
363	    // One invariant at the exit rather than a guard per failure path: **never publish an empty
364	    // set**. Several routes lead here — lazy generation failed, every stored key is unusable,
365	    // or some future path — and they all end the same way for a client, which pins nothing and
366	    // then cannot verify a single notification it receives. Checking the result instead of each
367	    // cause means a new failure mode is covered the day it appears.
368	    if keys.is_empty() {
369	        return Err(SenderKeyError::NoUsableKey);
370	    }
371	    Ok(keys)
372	}
373	
374	/// Why the published sender-key set could not be produced.
375	#[derive(Debug, thiserror::Error)]
376	pub enum SenderKeyError {
377	    #[error("notifications are configured but no signing-key master key is set")]
378	    NoMasterKey,
379	    /// A key could neither be minted nor unwrapped. Distinct from [`Self::NoMasterKey`] because
380	    /// the operator fix differs: the master key is present, so this is a generation failure or
381	    /// key material that no longer decrypts under it (both already logged with their cause).
382	    #[error("no usable notification sender key could be produced")]
383	    NoUsableKey,
384	    #[error(transparent)]
385	    Db(#[from] sqlx::Error),
386	}
387	
388	/// The master KEK, if configured. Callers report its absence — logging here would emit a line
389	/// per request on the read path, where the caller already turns it into a visible error.
390	fn master_key(state: &AppState) -> Option<&[u8; 32]> {
391	    state.config.signing_key_master_key.as_ref().map(|s| &*s.0)
392	}
393	
394	/// Narrow a decrypted secret to a 32-byte scalar without leaving `Zeroizing`.
395	///
396	/// `decrypt_secret_bytes` returns a `Zeroizing<Vec<u8>>`; converting through a bare array
397	/// would drop the wipe-on-drop guarantee for the copy, so the result is re-wrapped instead.
398	fn to_scalar(bytes: &[u8]) -> Option<Zeroizing<[u8; 32]>> {
399	    <[u8; 32]>::try_from(bytes).ok().map(Zeroizing::new)
400	}
401	
402	fn base64url(bytes: &[u8]) -> String {
403	    data_encoding::BASE64URL_NOPAD.encode(bytes)
404	}
405	
406	#[cfg(test)]
407	mod tests {
408	    use super::*;
409	
410	    fn recipient() -> (crypto::P256Keypair, Vec<u8>) {
411	        let keypair = crypto::generate_p256_keypair().unwrap();
412	        let public = crypto::p256_public_key_from_did_key(&keypair.key_id.0).unwrap();
413	        (keypair, public)
414	    }
415	
416	    /// The property the whole padding budget exists for: two notifications of very different
417	    /// natural length must produce APNs bodies of the *same* length.
418	    #[test]
419	    fn payloads_of_different_lengths_land_on_the_same_bucket() {
420	        let sender = crypto::generate_p256_keypair().unwrap();
421	        let (_, recipient_public) = recipient();
422	
423	        let body_len = |payload: &NotificationPayload| {
424	            let sealed =
425	                seal_for(1, &sender.private_key_bytes, &recipient_public, payload).unwrap();
426	            let envelope = notify_relay::protocol::apns_envelope(
427	                1,
428	                &base64url(&sealed.enc),
429	                &base64url(&sealed.ct),
430	            );
431	            serde_json::to_vec(&envelope).unwrap().len()
432	        };
433	
434	        let short = NotificationPayload::new("agent_claim_pending", "Custos", "hi");
435	        let long = NotificationPayload::new("agent_claim_pending", "Custos", "x".repeat(400))
436	            .with_data(serde_json::json!({ "claimAttemptId": "clm_0123456789" }));
437	        assert_ne!(
438	            serde_json::to_vec(&short).unwrap().len(),
439	            serde_json::to_vec(&long).unwrap().len(),
440	            "the two payloads must genuinely differ before padding"
441	        );
442	
443	        assert_eq!(
444	            body_len(&short),
445	            body_len(&long),
446	            "padding must erase the length difference between notification kinds"
447	        );
448	    }
449	
450	    #[test]
451	    fn every_sealed_body_stays_under_apples_cap() {
452	        let sender = crypto::generate_p256_keypair().unwrap();
453	        let (_, recipient_public) = recipient();
454	
455	        for body_len in [0usize, 1, 50, 500, 1500, 2400] {
456	            let payload =
457	                NotificationPayload::new("agent_claim_pending", "Custos", "b".repeat(body_len));
458	            let sealed =
459	                seal_for(1, &sender.private_key_bytes, &recipient_public, &payload).unwrap();
460	            let envelope = notify_relay::protocol::apns_envelope(
461	                1,
462	                &base64url(&sealed.enc),
463	                &base64url(&sealed.ct),
464	            );
465	            let len = serde_json::to_vec(&envelope).unwrap().len();
466	            assert!(
467	                len <= *crypto::PADDING_BUCKETS.last().unwrap(),
468	                "body_len {body_len} produced a {len}-byte body, past the top bucket"
469	            );
470	            assert!(len < crypto::APNS_MAX_PAYLOAD_BYTES);
471	        }
472	    }
473	
474	    /// The answer to "too big to pad" is refusal, not a degraded send.
475	    #[test]
476	    fn an_unpaddable_payload_is_refused_rather_than_sent_unpadded() {
477	        let sender = crypto::generate_p256_keypair().unwrap();
478	        let (_, recipient_public) = recipient();
479	
480	        let payload = NotificationPayload::new("agent_claim_pending", "Custos", "x".repeat(4096));
481	        assert!(seal_for(1, &sender.private_key_bytes, &recipient_public, &payload).is_none());
482	    }
483	
484	    /// The end-to-end crypto contract, from the device's point of view: the fixture "device"
485	    /// opens the payload and, in doing so, verifies it came from this instance's sender key.
486	    #[test]
487	    fn a_device_opens_the_payload_and_verifies_the_sender() {
488	        let sender = crypto::generate_p256_keypair().unwrap();
489	        let (recipient_keypair, recipient_public) = recipient();
490	
491	        let payload = NotificationPayload::new(
492	            "agent_claim_pending",
493	            "Confirm agent access",
494	            "An agent is waiting for you to confirm it.",
495	        )
496	        .with_data(serde_json::json!({ "claimAttemptId": "clm_abc" }));
497	        let sealed = seal_for(3, &sender.private_key_bytes, &recipient_public, &payload).unwrap();
498	
499	        let sender_public = crypto::public_key_for_secret(&sender.private_key_bytes).unwrap();
500	        let opened = crypto::open_notification(
501	            &recipient_keypair.private_key_bytes,
502	            &sender_public,
503	            &sealed.enc,
504	            &sealed.ct,
505	        )
506	        .unwrap();
507	
508	        let decoded: serde_json::Value = serde_json::from_slice(&opened).unwrap();
509	        assert_eq!(decoded["type"], "agent_claim_pending");
510	        assert_eq!(decoded["title"], "Confirm agent access");
511	        assert_eq!(decoded["data"]["claimAttemptId"], "clm_abc");
512	
513	        // Authenticity is not incidental: an impostor's key must not open it.
514	        let impostor = crypto::generate_p256_keypair().unwrap();
515	        let impostor_public = crypto::public_key_for_secret(&impostor.private_key_bytes).unwrap();
516	        assert!(crypto::open_notification(
517	            &recipient_keypair.private_key_bytes,
518	            &impostor_public,
519	            &sealed.enc,
520	            &sealed.ct
521	        )
522	        .is_err());
523	    }
524	
525	    #[tokio::test]
526	    async fn sending_is_inert_when_no_relay_is_configured() {
527	        let state = crate::state::test_state().await;
528	        assert!(state.notify_sender.is_none());
529	
530	        // No relay, no panic, no rows touched — the whole feature is absent.
531	        notify_device(
532	            &state,
533	            "did:plc:nobody",
534	            NotificationPayload::new("agent_claim_pending", "t", "b"),
535	        )
536	        .await;
537	        notify_admin_devices(&state, NotificationPayload::new("ops_alert", "t", "b")).await;
538	
539	        let keys: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM notification_sender_keys")
540	            .fetch_one(&state.db)
541	            .await
542	            .unwrap();
543	        assert_eq!(keys, 0, "an inert feature must not mint key material");
544	    }
545	}
