103	    let service = Arc::new(notify_relay::service::RelayService::new(pool, config).with_apns(apns));
104	    let endpoint = loopback_endpoint(true).await;
105	    notify_relay::transport::spawn_accept_loop(endpoint.clone(), Arc::clone(&service));
106	    (endpoint, service, dir)
107	}
108	
109	/// A pds wired to dial the relay at `relay_addr`, with notifications configured.
110	async fn start_pds(relay_addr: EndpointAddr) -> (AppState, Endpoint) {
111	    let mut state = crate::state::test_state().await;
112	
113	    let mut config = (*state.config).clone();
114	    // A node id is required for the feature to be considered configured; the client dials
115	    // `relay_addr` directly, since loopback has no discovery to resolve this against.
116	    config.notifications.relay = Some(relay_addr.id.to_string());
117	    config.iroh.enabled = true;
118	    config.signing_key_master_key = Some(common::Sensitive(zeroize::Zeroizing::new(MASTER_KEY)));
119	    state.config = Arc::new(config);
120	
121	    let dialer = loopback_endpoint(false).await;
122	    let client =
123	        crate::notify_relay_client::NotifyRelayClient::with_addr(dialer.clone(), relay_addr, None);
124	    let (sender, _worker) = crate::notify_relay_client::spawn_worker(
125	        Arc::new(client),
126	        state.db.clone(),
127	        state.metrics.clone(),
128	    );
129	    state.notify_sender = Some(sender);
130	
131	    sqlx::query(
132	        "INSERT INTO accounts (did, email, password_hash, created_at, updated_at) \
133	         VALUES (?, 'e2e@example.com', 'hash', datetime('now'), datetime('now'))",
134	    )
135	    .bind(ACCOUNT_DID)
136	    .execute(&state.db)
137	    .await
138	    .expect("seed account");
139	
140	    (state, dialer)
141	}
142	
143	fn access_token(state: &AppState) -> String {
144	    #[derive(serde::Serialize)]
145	    struct Claims {
146	        sub: String,
147	        aud: String,
148	        exp: u64,
149	        scope: String,
150	    }
151	    jsonwebtoken::encode(
152	        &jsonwebtoken::Header::new(jsonwebtoken::Algorithm::HS256),
153	        &Claims {
154	            sub: ACCOUNT_DID.to_string(),
155	            aud: "did:plc:test".to_string(),
156	            exp: (chrono::Utc::now().timestamp() + 3600) as u64,
157	            scope: "com.atproto.access".to_string(),
158	        },
159	        &jsonwebtoken::EncodingKey::from_secret(&state.jwt_secret),
160	    )
161	    .expect("token")
162	}
163	
164	/// Register `device_public_key` through the real HTTP route, then wait for the background
165	/// worker to complete the relay round trip.
166	async fn register_device(state: &AppState, device_public_key: &str) {
167	    let response = crate::app::app(state.clone())
168	        .oneshot(
169	            Request::post("/v1/notifications/register")
170	                .header("authorization", format!("Bearer {}", access_token(state)))
171	                .header("content-type", "application/json")
172	                .body(Body::from(
173	                    json!({
174	                        "deviceUuid": DEVICE_UUID,
175	                        "notificationPublicKey": device_public_key,
176	                        "apnsToken": "deadbeef0123456789",
177	                        "apnsTopic": "org.obsign.identitywallet",
178	                    })
179	                    .to_string(),
180	                ))
181	                .unwrap(),
182	        )
183	        .await
184	        .expect("register response");
185	    assert_eq!(response.status(), StatusCode::OK);
186	
187	    // The route returns before the relay knows anything — that is the deliberate design.
188	    // Wait for the handle rather than sleeping a fixed amount, so the test is not timing-luck.
189	    let handle = await_condition("a relay push handle", || async {
190	        store::list_registrations(&state.db, ACCOUNT_DID)
191	            .await
192	            .ok()
193	            .and_then(|rows| rows.into_iter().next())
194	            .and_then(|row| row.push_handle)
195	    })
196	    .await;
197	    assert!(!handle.is_empty());
198	}
199	
200	/// Poll `probe` until it yields a value, or fail the test. Condition-based rather than a
201	/// fixed sleep: the worker is asynchronous, and a sleep would either be flaky or slow.
202	async fn await_condition<T, F, Fut>(what: &str, mut probe: F) -> T
203	where
204	    F: FnMut() -> Fut,
205	    Fut: std::future::Future<Output = Option<T>>,
206	{
207	    let deadline = tokio::time::Instant::now() + Duration::from_secs(20);
208	    loop {
209	        if let Some(value) = probe().await {
210	            return value;
211	        }
212	        assert!(
213	            tokio::time::Instant::now() < deadline,
214	            "timed out waiting for {what}"
215	        );
216	        tokio::time::sleep(Duration::from_millis(25)).await;
217	    }
218	}
219	
220	/// The instance's published sender key, as a device would fetch and pin it.
221	async fn published_sender_key(state: &AppState) -> (i64, Vec<u8>) {
222	    let keys = crate::notifications::published_sender_keys(state)
223	        .await
224	        .expect("published keys");
225	    let (kid, did_key) = keys.into_iter().next().expect("at least one sender key");
226	    (
227	        kid,
228	        crypto::p256_public_key_from_did_key(&did_key).expect("a decodable did:key"),
229	    )
230	}
231	
232	/// The full happy path: register, seal, push — and the device opens it.
233	#[tokio::test]
234	async fn a_notification_travels_from_custos_through_the_relay_to_a_device_that_opens_it() {
235	    let apple = MockServer::start().await;
236	    Mock::given(method("POST"))
237	        .respond_with(ResponseTemplate::new(200))
238	        .mount(&apple)
239	        .await;
240	
241	    let (relay_endpoint, _relay, _keydir) = start_relay(&apple.uri()).await;
242	    let relay_addr =
243	        EndpointAddr::new(relay_endpoint.id()).with_ip_addr(relay_endpoint.bound_sockets()[0]);
244	    let (state, dialer) = start_pds(relay_addr).await;
245	
246	    // The "device": a keypair the app would generate and register.
247	    let device = crypto::generate_p256_keypair().expect("device keypair");
248	    register_device(&state, &device.key_id.0).await;
249	
250	    let (kid, sender_public_key) = published_sender_key(&state).await;
251	
252	    crate::notifications::notify_device(
253	        &state,
254	        ACCOUNT_DID,
255	        crate::notifications::NotificationPayload::new(
256	            "agent_claim_pending",
257	            "Confirm agent access",
258	            "An agent is waiting for you to approve it.",
259	        )
260	        .with_data(json!({ "claimAttemptId": "clm_e2e" })),
261	    )
262	    .await;
263	
264	    // Apple's first request is the registration-time nothing; the push is the one with a body
265	    // carrying our envelope. Wait for it rather than assuming ordering.
266	    // Keep the raw byte length alongside the parsed value: the padding assertion below has to
267	    // measure what actually crossed the wire, since parse-and-reserialize could normalize away
268	    // the very size drift it is there to catch.
269	    let (serialized_len, body) = await_condition("the pushed APNs body", || async {
270	        apple
271	            .received_requests()
272	            .await
273	            .unwrap_or_default()
274	            .into_iter()
275	            .find_map(|req| {
276	                serde_json::from_slice::<serde_json::Value>(&req.body)
277	                    .ok()
278	                    .map(|parsed| (req.body.len(), parsed))
279	            })
280	    })
281	    .await;
282	
283	    // What Apple (and the relay) can see: a fixed, content-free placeholder. The actual
284	    // notification is opaque to both.
285	    assert_eq!(body["aps"]["alert"]["title"], "Custos");
286	    assert_eq!(body["aps"]["alert"]["body"], "Encrypted notification");
287	    assert_eq!(body["aps"]["mutable-content"], 1);
288	    assert_eq!(body["ezpds"]["v"], 1);
289	    assert_eq!(
290	        body["ezpds"]["kid"], kid,
291	        "the envelope must name the key the instance published"
292	    );
293	
294	    // The body Apple received must sit on a padding bucket — the assertion that catches the two
295	    // crates disagreeing about the envelope's shape, since Custos computed the pad against its
296	    // own model of these very bytes. The one-byte tolerance is not slack: base64's four-chars-
297	    // per-three-bytes step makes some bucket targets unreachable, so `plaintext_pad_len`
298	    // documents (and its own tests pin) landing on the bucket or one byte under it.
299	    assert!(
300	        crypto::PADDING_BUCKETS.contains(&serialized_len)
301	            || crypto::PADDING_BUCKETS.contains(&(serialized_len + 1)),
302	        "body was {serialized_len} bytes, not on a padding bucket {:?}",
303	        crypto::PADDING_BUCKETS
304	    );
305	
306	    // Now the device's half: open the payload, which also *verifies the sender*. HPKE
307	    // mode_auth means a successful open is proof the instance's sender key sealed it — the
308	    // relay could not have authored this.
309	    let decode = |field: &str| {
310	        data_encoding::BASE64URL_NOPAD
311	            .decode(body["ezpds"][field].as_str().expect("string").as_bytes())
312	            .expect("base64url")
313	    };
314	    let plaintext = crypto::open_notification(
315	        &device.private_key_bytes,
316	        &sender_public_key,
317	        &decode("enc"),
318	        &decode("ct"),
319	    )
320	    .expect("the device must be able to open a payload sealed to it");
321	
322	    let opened: serde_json::Value = serde_json::from_slice(&plaintext).expect("payload JSON");
323	    assert_eq!(opened["type"], "agent_claim_pending");
324	    assert_eq!(opened["title"], "Confirm agent access");
325	    assert_eq!(opened["data"]["claimAttemptId"], "clm_e2e");
326	
327	    // An impostor holding the same ciphertext cannot make it verify as ours.
328	    let impostor = crypto::generate_p256_keypair().expect("impostor keypair");
329	    let impostor_public = crypto::public_key_for_secret(&impostor.private_key_bytes).unwrap();
330	    assert!(
331	        crypto::open_notification(
332	            &device.private_key_bytes,
333	            &impostor_public,
334	            &decode("enc"),
335	            &decode("ct"),
336	        )
337	        .is_err(),
338	        "mode_auth must refuse a payload attributed to the wrong sender"
339	    );
340	
341	    dialer.close().await;
342	    relay_endpoint.close().await;
343	}
344	
345	/// Phase C of wallet-confirmed OAuth consent, end to end on the server side: a login started
346	/// on another surface (`GET /oauth/authorize` with a `login_hint` naming a hosted account)
347	/// produces a sealed `login-approval` push through the real relay; the device opens it and
348	/// finds the routing data; the login page displays the mandatory match number; and the relay
349	/// and Apple see only the fixed placeholder — they never learn a login is happening.
350	#[tokio::test]
351	async fn a_hinted_login_pushes_a_sealed_login_approval_to_the_wallet() {
352	    let apple = MockServer::start().await;
353	    Mock::given(method("POST"))
354	        .respond_with(ResponseTemplate::new(200))
355	        .mount(&apple)
356	        .await;
357	
358	    let (relay_endpoint, _relay, _keydir) = start_relay(&apple.uri()).await;
359	    let relay_addr =
360	        EndpointAddr::new(relay_endpoint.id()).with_ip_addr(relay_endpoint.bound_sockets()[0]);
361	    let (state, dialer) = start_pds(relay_addr).await;
362	
363	    // A hosted, handle-bearing account with a registered wallet device.
364	    sqlx::query("INSERT INTO handles (handle, did, created_at) VALUES (?, ?, datetime('now'))")
365	        .bind("notifye2e.example.com")
366	        .bind(ACCOUNT_DID)
367	        .execute(&state.db)
368	        .await
369	        .expect("seed handle");
370	    let device = crypto::generate_p256_keypair().expect("device keypair");
371	    register_device(&state, &device.key_id.0).await;
372	    let (_kid, sender_public_key) = published_sender_key(&state).await;
373	
374	    // A registered OAuth client, and the login another device starts against it.
375	    crate::db::oauth::register_oauth_client(
376	        &state.db,
377	        "https://app.example.com/client-metadata.json",
378	        r#"{"redirect_uris":["https://app.example.com/callback"],"client_name":"Test App"}"#,
379	    )
380	    .await
381	    .expect("register client");
382	
383	    let response = crate::app::app(state.clone())
384	        .oneshot(
385	            Request::get(
386	                "/oauth/authorize\
387	                 ?client_id=https%3A%2F%2Fapp.example.com%2Fclient-metadata.json\
388	                 &redirect_uri=https%3A%2F%2Fapp.example.com%2Fcallback\
389	                 &code_challenge=e3b0c44298fc1c149afb\
390	                 &code_challenge_method=S256\
391	                 &state=teststate\
392	                 &response_type=code\
393	                 &scope=atproto\
394	                 &login_hint=notifye2e.example.com",
395	            )
396	            .body(Body::empty())
397	            .unwrap(),
398	        )
399	        .await
400	        .expect("consent page");
401	    assert_eq!(response.status(), StatusCode::OK);
402	    let html_bytes = axum::body::to_bytes(response.into_body(), 1 << 20)
403	        .await
404	        .expect("page body");
405	    let html = std::str::from_utf8(&html_bytes).expect("utf8 page");
406	
407	    // The pending row latched the match code, and the page displays that exact number.
408	    let (request_id, match_code): (String, String) = sqlx::query_as(
409	        "SELECT request_id, match_code FROM pending_oauth_authorizations WHERE match_code IS NOT NULL",
410	    )
411	    .fetch_one(&state.db)
412	    .await
413	    .expect("a push-dispatched pending row");
414	    assert!(
415	        html.contains(&format!(
416	            "<div class=\"match-code mono\" id=\"match-code\">{match_code}</div>"
417	        )),
418	        "the login surface must display the match number"
419	    );
420	
421	    // The push that crossed the wire: placeholder alert outside, `login-approval` inside.
422	    let body = await_condition("the pushed APNs body", || async {
423	        apple
424	            .received_requests()
425	            .await
426	            .unwrap_or_default()
427	            .into_iter()
428	            .find_map(|req| serde_json::from_slice::<serde_json::Value>(&req.body).ok())
429	    })
430	    .await;
431	    assert_eq!(body["aps"]["alert"]["title"], "Custos");
432	    assert_eq!(body["aps"]["alert"]["body"], "Encrypted notification");
433	
434	    let decode = |field: &str| {
435	        data_encoding::BASE64URL_NOPAD
436	            .decode(body["ezpds"][field].as_str().expect("string").as_bytes())
437	            .expect("base64url")
438	    };
439	    let plaintext = crypto::open_notification(
440	        &device.private_key_bytes,
441	        &sender_public_key,
442	        &decode("enc"),
443	        &decode("ct"),
444	    )
445	    .expect("the device must open the login-approval payload");
446	    let opened: serde_json::Value = serde_json::from_slice(&plaintext).expect("payload JSON");
447	    assert_eq!(opened["type"], "login-approval");
448	    assert_eq!(opened["data"]["requestId"], request_id.as_str());
449	    assert_eq!(opened["data"]["did"], ACCOUNT_DID);
450	    assert_eq!(opened["data"]["clientName"], "Test App");
451	    // The match number must never ride in the push — it is the proof the approver can see the
452	    // login surface, so handing it to the wallet would defeat the channel binding. (Asserted on
453	    // the parsed fields, not a substring: a two-digit string can appear by chance inside the
454	    // random request_id.)
455	    assert!(
456	        opened.get("code").is_none() && opened["data"].get("code").is_none(),
457	        "no code field may ride in the push payload"
458	    );
459	
460	    dialer.close().await;
461	    relay_endpoint.close().await;
462	}
463	
464	/// The pruning back-channel: Apple reports the device token dead, the relay relays that as
465	/// `unregistered`, and Custos deletes the registration at the moment of proof.
466	#[tokio::test]
467	async fn a_dead_device_token_prunes_its_registration() {
468	    let apple = MockServer::start().await;
469	    Mock::given(method("POST"))
470	        .respond_with(ResponseTemplate::new(410))
471	        .mount(&apple)
472	        .await;
473	
474	    let (relay_endpoint, _relay, _keydir) = start_relay(&apple.uri()).await;
475	    let relay_addr =
476	        EndpointAddr::new(relay_endpoint.id()).with_ip_addr(relay_endpoint.bound_sockets()[0]);
477	    let (state, dialer) = start_pds(relay_addr).await;
478	
479	    let device = crypto::generate_p256_keypair().expect("device keypair");
480	    register_device(&state, &device.key_id.0).await;
481	
482	    crate::notifications::notify_device(
483	        &state,
484	        ACCOUNT_DID,
