#[serde(rename_all = "camelCase")]
pub struct SenderKey {
    /// Version. Every sealed payload's envelope names which key sealed it.
    pub kid: i64,
    /// The P-256 `did:key` to verify against.
    pub public_key: String,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SenderKeysResponse {

